/**
 * The SAL logo files , used exactly as supplied in
 * packages/brand/assets/logos and copied byte-for-byte to the app's public/brand
 * (tokens.test.ts checks). Never redrawn, recolored or rebuilt in code. The
 * light files are for white and paper; the reversed files for crimson and
 * ink. The logo appears once per page.
 */
interface LogoFile {
  /** Width ÷ height, from the file's viewBox. */
  readonly aspect: number;
  readonly onDark: string;
  readonly onLight: string;
}

export const logos = {
  /** Anything public: the homepage hero, calls, certificates. */
  bilingual: {
    aspect: 3290.11 / 1099.22,
    onDark: "/brand/sal-lockup-bilingual-reversed.svg",
    onLight: "/brand/sal-lockup-bilingual.svg",
  },
  /** The default on English pages: headers, covers, letterheads. */
  horizontal: {
    aspect: 2017.86 / 1009,
    onDark: "/brand/sal-lockup-horizontal-reversed.svg",
    onLight: "/brand/sal-lockup-horizontal.svg",
  },
  /** The default on Arabic pages: the Arabic lockup, symbol on the right. */
  "horizontal-ar": {
    aspect: 2108.2 / 1099.22,
    onDark: "/brand/sal-lockup-horizontal-ar-reversed.svg",
    onLight: "/brand/sal-lockup-horizontal-ar.svg",
  },
  /** Square spaces, stickers and merchandise. */
  stacked: {
    aspect: 997.8 / 1857.19,
    onDark: "/brand/sal-lockup-stacked-reversed.svg",
    onLight: "/brand/sal-lockup-stacked.svg",
  },
  /** The symbol alone, once the name appears elsewhere (24 px tall minimum). */
  symbol: {
    aspect: 864 / 1039,
    onDark: "/brand/sal-symbol-white.svg",
    onLight: "/brand/sal-symbol.svg",
  },
} as const satisfies Record<string, LogoFile>;

export type LogoVariant = keyof typeof logos;

